import { useMemo } from 'react'
import { useUserTokens } from 'uniswap/src/contexts/UserTokensContext'
import { getCommonBase } from 'uniswap/src/constants/routing'
import { getDexTokenList } from 'uniswap/src/constants/tokens'
import { useTokenQuery, useTokensQuery } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { SafetyLevel } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { currencyIdToContractInput, gqlTokenToCurrencyInfo } from 'uniswap/src/features/dataApi/utils'
import { getTokenLogoUrl } from 'uniswap/src/constants/tokenLogos'
import {
  buildNativeCurrencyId,
  buildWrappedNativeCurrencyId,
  currencyIdToAddress,
  currencyIdToChain,
  isNativeCurrencyAddress,
} from 'uniswap/src/utils/currencyId'

export function useCurrencyInfo(
  _currencyId?: string,
  options?: { refetch?: boolean; skip?: boolean },
): Maybe<CurrencyInfo> {
  const { userAddedTokens } = useUserTokens()
  // Skip GraphQL query to avoid external API calls
  return useMemo(() => {
    if (!_currencyId || options?.skip) {
      return undefined
    }

    const chainId = currencyIdToChain(_currencyId)
    let address: Address | undefined
    try {
      address = currencyIdToAddress(_currencyId)
    } catch (error) {
      return undefined
    }
    
    if (chainId && address) {
      // First, check common base tokens
      const commonBase = getCommonBase(chainId, isNativeCurrencyAddress(chainId, address), address)
      if (commonBase) {
        // Creating new object to avoid error "Cannot assign to read only property"
        const copyCommonBase = { ...commonBase }
        copyCommonBase.currencyId = _currencyId
        return copyCommonBase
      }

      // Second, check DEX token list
      const dexTokens = getDexTokenList(chainId)
      const dexToken = dexTokens.find(
        token => token.address.toLowerCase() === address.toLowerCase()
      )

      if (dexToken) {
        return {
          currency: dexToken,
          currencyId: _currencyId,
          safetyLevel: SafetyLevel.Verified,
          logoUrl: getTokenLogoUrl(address),
        }
      }

      // Third, check user imported tokens
      if (userAddedTokens) {
        const userToken = userAddedTokens.find(
          token => token.chainId === chainId &&
          token.address.toLowerCase() === address.toLowerCase()
        )

        if (userToken) {
          return {
            currency: userToken,
            currencyId: _currencyId,
            safetyLevel: SafetyLevel.MediumWarning, // Mark imported tokens with warning
            logoUrl: getTokenLogoUrl(address),
          }
        }
      }
    }

    // Return undefined instead of making GraphQL call
    return undefined
  }, [_currencyId, options?.skip, userAddedTokens])
}

export function useCurrencyInfos(
  _currencyIds: string[],
  options?: { refetch?: boolean; skip?: boolean },
): Maybe<CurrencyInfo>[] {
  const { userAddedTokens } = useUserTokens()
  
  return useMemo(() => {
    if (!_currencyIds.length || options?.skip) {
      return []
    }
    
    // Process each currency ID using the same logic as useCurrencyInfo
    return _currencyIds.map(currencyId => {
      if (!currencyId) {
        return undefined
      }

      const chainId = currencyIdToChain(currencyId)
      let address: Address | undefined
      try {
        address = currencyIdToAddress(currencyId)
      } catch (error) {
        return undefined
      }
      
      if (chainId && address) {
        // First, check common base tokens
        const commonBase = getCommonBase(chainId, isNativeCurrencyAddress(chainId, address), address)
        if (commonBase) {
          // Creating new object to avoid error "Cannot assign to read only property"
          const copyCommonBase = { ...commonBase }
          copyCommonBase.currencyId = currencyId
          return copyCommonBase
        }

        // Second, check DEX token list
        const dexTokens = getDexTokenList(chainId)
        const dexToken = dexTokens.find(
          token => token.address.toLowerCase() === address.toLowerCase()
        )

        if (dexToken) {
          return {
            currency: dexToken,
            currencyId: currencyId,
            safetyLevel: SafetyLevel.Verified,
            logoUrl: getTokenLogoUrl(address),
          }
        }

        // Third, check user imported tokens
        if (userAddedTokens) {
          const userToken = userAddedTokens.find(
            token => token.chainId === chainId &&
            token.address.toLowerCase() === address.toLowerCase()
          )

          if (userToken) {
            return {
              currency: userToken,
              currencyId: currencyId,
              safetyLevel: SafetyLevel.MediumWarning, // Mark imported tokens with warning
              logoUrl: getTokenLogoUrl(address),
            }
          }
        }
      }

      // Return undefined if no match found
      return undefined
    })
  }, [_currencyIds, options?.skip, userAddedTokens])
}

export function useNativeCurrencyInfo(chainId: UniverseChainId): Maybe<CurrencyInfo> {
  const nativeCurrencyId = buildNativeCurrencyId(chainId)
  return useCurrencyInfo(nativeCurrencyId)
}

export function useWrappedNativeCurrencyInfo(chainId: UniverseChainId): Maybe<CurrencyInfo> {
  const wrappedCurrencyId = buildWrappedNativeCurrencyId(chainId)
  return useCurrencyInfo(wrappedCurrencyId)
}
