import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { getAbstractContracts } from 'uniswap/src/constants/abstractContracts'

// Common intermediaries for multi-hop discovery.
// Keep this easy to update; seed with WETH and USDC (Abstract testnet/mainnet).
// Prefer to follow V2's topology-based discovery and use these as prioritized bases.

export function getCommonIntermediaries(chainId?: UniverseChainId): string[] {
  const effectiveChainId = chainId || UniverseChainId.Mainnet
  const contracts = getAbstractContracts(effectiveChainId)

  // Get WETH address for the chain
  const WETH = contracts?.weth?.toLowerCase() || '0x3439153EB7AF838Ad19d56E1571FBD09333C2809'

  // Chain-specific tokens
  if (effectiveChainId === UniverseChainId.Sepolia) {
    // Abstract Testnet
    const USDC = '0x698f98ab816670692fa9dd8e1486ea0fd253e996'
    const USDT = '0xfaf7f84baacf74d9b6b70f201479d792e936f8a5'
    const ABX = '0xb6313be1c20dc222199ec567951abc6b5b64dfd6'
    return [WETH, USDC, USDT, ABX]
  } else {
    // Abstract Mainnet
    const USDC = '0x84a71ccd554cc1b02749b35d22f684cc8ec987e1' // Mainnet USDC.e (bridged USDC via Stargate)
    const USDT = '0x0709f39376deee2a2dfc94a58edeb2eb9df012bd' // Mainnet USDT
    const ABX = '0x4c68e4102c0f120cce9f08625bd12079806b7c4d' // Mainnet ABX
    return [WETH, USDC, USDT, ABX]
  }
}

