export function useProfileCache() {
  const [cache, setCache] = useState(/* @__PURE__ */ new Map());
  const getProfile = useCallback(
    (address) => {
      return cache.get(address) || null;
    },
    [cache]
  );
  const setProfile = useCallback((address, profile) => {
    setCache((prev) => new Map(prev).set(address, profile));
  }, []);
  const loadProfiles = useCallback(
    async (addresses) => {
      const uncachedAddresses = addresses.filter((addr) => !cache.has(addr));
      if (uncachedAddresses.length === 0) {
        return;
      }
      try {
        const profileMap = await profileApi.getMultipleUserProfiles(uncachedAddresses);
        setCache((prev) => {
          const newCache = new Map(prev);
          profileMap.forEach((profile, address) => {
            newCache.set(address, profile);
          });
          return newCache;
        });
      } catch (error) {
        console.warn("Failed to load profiles:", error);
      }
    },
    [cache]
  );
  const clearCache = useCallback(() => {
    setCache(/* @__PURE__ */ new Map());
  }, []);
  return {
    getProfile,
    setProfile,
    loadProfiles,
    clearCache,
    cacheSize: cache.size
  };
}
