async function fetchUnifiedPositions(userAddress, chainId, skip = 0, first = 100) {
  const subgraphs = getAbstractSubgraphs(chainId);
  const positionsSubgraph = subgraphs.positions;
  try {
    const result = await fetchFromSubgraph(positionsSubgraph, {
      query: GET_USER_POSITIONS,
      variables: {
        userAddress: userAddress.toLowerCase(),
        first,
        skip
      },
      requestId: "useSimpleAbstractPositions"
    });
    if (!result?.user) {
      console.log("\u2139\uFE0F [UNIFIED_POSITIONS] No user found for address:", userAddress);
      return [];
    }
    const positions = result.user.positions || [];
    console.log(`\u2705 [UNIFIED_POSITIONS] Fetched ${positions.length} positions for ${userAddress}`);
    const mappedPositions = [];
    for (const pos of positions) {
      try {
        const positionInfo = mapSubgraphPositionToPositionInfo(pos, chainId);
        mappedPositions.push(positionInfo);
      } catch (error) {
        console.error(`\u274C [UNIFIED_POSITIONS] Failed to map position ${pos.id}:`, error, pos);
      }
    }
    if (mappedPositions.length < positions.length) {
      console.warn(`\u26A0\uFE0F [UNIFIED_POSITIONS] Successfully mapped ${mappedPositions.length}/${positions.length} positions`);
    }
    return mappedPositions;
  } catch (error) {
    console.error("\u274C [UNIFIED_POSITIONS] Fetch failed:", error);
    throw error;
  }
}
async function enrichPositionsWithOnchainData({
  positions,
  userAddress,
  chainId,
  provider
}) {
  if (!provider || positions.length === 0) {
    return positions;
  }
  const enrichedPositions = positions.map((position) => ({ ...position }));
  const v2Requests = enrichedPositions.filter((position) => position.version === ProtocolVersion.V2 && position.poolId).map((position) => ({
    poolAddress: position.poolId,
    userAddress,
    gaugeAddress: position.gaugeAddress,
    includeGaugeData: Boolean(position.gaugeAddress)
  }));
  if (v2Requests.length > 0) {
    try {
      const { fees: v2Fees, gauges: v2GaugeInfo } = await fetchAbstractV2FeesBatch({ provider, requests: v2Requests });
      enrichedPositions.forEach((position, index) => {
        if (position.version !== ProtocolVersion.V2 || !position.poolId) {
          return;
        }
        const fees = v2Fees.get(position.poolId.toLowerCase());
        const gaugeInfo = position.gaugeAddress ? v2GaugeInfo.get(position.gaugeAddress.toLowerCase()) : void 0;
        const resolvedStakedRaw = gaugeInfo?.userBalance ?? position.stakedAmount;
        const resolvedUnstakedRaw = fees?.walletBalance ?? position.unstakedAmount;
        let stakedAmountBigInt = 0n;
        let unstakedAmountBigInt = 0n;
        try {
          stakedAmountBigInt = resolvedStakedRaw ? BigInt(resolvedStakedRaw) : 0n;
        } catch {
          stakedAmountBigInt = 0n;
        }
        try {
          unstakedAmountBigInt = resolvedUnstakedRaw ? BigInt(resolvedUnstakedRaw) : 0n;
        } catch {
          unstakedAmountBigInt = 0n;
        }
        const totalLp = stakedAmountBigInt + unstakedAmountBigInt;
        const hasStakedBalance = stakedAmountBigInt > 0n;
        const hasUnstakedBalance = unstakedAmountBigInt > 0n;
        const isPartiallyStaked = hasStakedBalance && hasUnstakedBalance;
        const isFullyStaked = hasStakedBalance && !hasUnstakedBalance;
        const stakingPercentage = totalLp > 0n ? Number(stakedAmountBigInt * 10000n / totalLp) / 100 : position.stakingPercentage;
        enrichedPositions[index] = {
          ...position,
          token0UncollectedFees: fees?.amount0 ?? position.token0UncollectedFees,
          token1UncollectedFees: fees?.amount1 ?? position.token1UncollectedFees,
          gaugeRewardRateRaw: gaugeInfo?.rewardRate ?? position.gaugeRewardRateRaw,
          gaugeTotalStakedRaw: gaugeInfo?.totalStaked ?? position.gaugeTotalStakedRaw,
          gaugeStakeAmount: resolvedStakedRaw ?? position.gaugeStakeAmount,
          stakedAmount: resolvedStakedRaw ?? position.stakedAmount,
          unstakedAmount: resolvedUnstakedRaw ?? position.unstakedAmount,
          hasGaugeStake: hasStakedBalance || position.hasGaugeStake,
          isStaked: isFullyStaked,
          isPartiallyStaked,
          stakingPercentage
        };
      });
    } catch (error) {
      console.warn("[UNIFIED_POSITIONS] Failed to apply V2 fee batch updates", error);
    }
  }
  const v3Requests = enrichedPositions.filter((position) => position.version === ProtocolVersion.V3 && position.tokenId).map((position) => ({
    tokenId: position.tokenId,
    ownerAddress: position.owner,
    gaugeAddress: position.gaugeAddress,
    isStaked: position.isStaked,
    recipientAddress: userAddress
  }));
  if (v3Requests.length > 0) {
    try {
      const { tradingFees, gaugeRewards, gaugeInfo } = await fetchAbstractV3FeesBatch({
        provider,
        chainId,
        userAddress,
        requests: v3Requests
      });
      enrichedPositions.forEach((position, index) => {
        if (position.version !== ProtocolVersion.V3 || !position.tokenId) {
          return;
        }
        const trading = tradingFees.get(position.tokenId);
        const gaugeReward = gaugeRewards.get(position.tokenId);
        const gaugeMeta = position.gaugeAddress ? gaugeInfo.get(position.gaugeAddress.toLowerCase()) : void 0;
        enrichedPositions[index] = {
          ...position,
          token0UncollectedFees: trading?.amount0 ?? position.token0UncollectedFees,
          token1UncollectedFees: trading?.amount1 ?? position.token1UncollectedFees,
          gaugePendingRewardsRaw: gaugeReward ?? position.gaugePendingRewardsRaw,
          gaugeRewardRateRaw: gaugeMeta?.rewardRate ?? position.gaugeRewardRateRaw,
          gaugeTotalStakedRaw: gaugeMeta?.totalStakedLiquidity ?? position.gaugeTotalStakedRaw
        };
      });
    } catch (error) {
      console.warn("[UNIFIED_POSITIONS] Failed to apply V3 fee batch updates", error);
    }
  }
  return enrichedPositions;
}
export function useSimpleAbstractPositions({
  address,
  chainIds,
  positionStatuses,
  protocolVersions
}) {
  const chainId = chainIds && chainIds.filter((c) => c != null)[0] || UniverseChainId.Mainnet;
  const provider = useEthersProvider({ chainId });
  const [enrichedPositions, setEnrichedPositions] = useState();
  const [isFetchingOnchain, setIsFetchingOnchain] = useState(false);
  const query = useQuery({
    queryKey: [
      "unified-positions",
      address?.toLowerCase(),
      chainId,
      positionStatuses,
      protocolVersions,
      Boolean(provider)
    ],
    queryFn: async () => {
      if (!address) return [];
      return fetchUnifiedPositions(address, chainId);
    },
    enabled: !!address,
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4,
    // 1 minute
    refetchOnWindowFocus: true,
    retry: 2,
    select: (positions2) => {
      let filtered = positions2;
      if (protocolVersions && protocolVersions.length > 0) {
        filtered = filtered.filter((pos) => protocolVersions.includes(pos.version));
      }
      if (positionStatuses && positionStatuses.length > 0) {
        filtered = filtered.filter((pos) => positionStatuses.includes(pos.status));
      }
      return filtered;
    }
  });
  useEffect(() => {
    if (!address || !query.data || query.data.length === 0) {
      setEnrichedPositions(void 0);
      setIsFetchingOnchain(false);
      return;
    }
    if (!provider) {
      setEnrichedPositions(void 0);
      setIsFetchingOnchain(false);
      return;
    }
    let cancelled = false;
    setIsFetchingOnchain(true);
    setEnrichedPositions(void 0);
    enrichPositionsWithOnchainData({
      positions: query.data,
      userAddress: address,
      chainId,
      provider
    }).then((updated) => {
      if (!cancelled) {
        setEnrichedPositions(updated);
      }
    }).catch((error) => {
      if (!cancelled) {
        console.warn("[UNIFIED_POSITIONS] Failed to enrich positions on-chain", error);
        setEnrichedPositions(query.data);
      }
    }).finally(() => {
      if (!cancelled) {
        setIsFetchingOnchain(false);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [address, chainId, provider, query.data, query.dataUpdatedAt]);
  const positions = enrichedPositions ?? query.data;
  return {
    data: positions ? {
      pages: [{ positions }]
    } : void 0,
    isLoading: query.isLoading,
    isPlaceholderData: query.isPlaceholderData,
    refetch: query.refetch,
    isFetching: query.isFetching,
    isError: query.isError,
    error: query.error,
    isFetchingOnchain,
    // Pagination not needed with unified subgraph (all positions in one query)
    fetchNextPage: () => Promise.resolve(),
    hasNextPage: false
  };
}
